-- Diseño «lienzo» + portada con foto para los correos de las cadencias Leads, Demo y Crecimiento
-- (23 plantillas). Misma receta que migration-rezagados-diseno-lienzo.sql: layout='lienzo' y un
-- bloque 'portada' al frente; si el correo abría con una foto de cuerpo, esa foto baja antes del
-- primer aviso para no quedar pegada a la portada.
begin;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/equipo.jpg","alt":"","etiqueta":"Lo que sigue · 1 de 10","titulo":"Lo estás usando bien, y hay más"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, este correo no es para venderte nada hoy."},{"id":"t2","tipo":"texto","texto":"Es para decirte algo que desde aquí se ve y desde adentro no: **estás usando Sacs bien**. Vendes, cortas caja, mueves inventario. Muchos clientes se quedan a la mitad de eso."},{"id":"s0","tipo":"separador"},{"id":"t3","tipo":"texto","texto":"Y justamente por eso te escribo. Cuando alguien ya domina la operación del día a día, lo que sigue deja de ser «aprender el sistema» y pasa a ser otra cosa: **qué más se puede quitar de encima**."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Lo que vamos a enseñarte estas semanas"},{"id":"l1","tipo":"lista","items":["🤖 **Axo**, el asistente con IA que hace el trabajo en vez de explicarte cómo hacerlo.","👥 **Empleados**, para asistencias, contratos, actas y clima laboral.","🏦 **Administración**, con gastos, cuentas por cobrar y por pagar.","📦 **Nivelación**, que te avisa qué mover entre sucursales y qué comprar.","🧩 **Personalizaciones**, para automatizar un proceso tuyo que hoy es a mano."]},{"id":"a1","tipo":"aviso","texto":"Uno por correo, cada dos semanas. Son **extensiones** de tu plan actual — no vienen incluidas, y no las vas a encontrar con un precio de lista: **cada una se ve contigo por WhatsApp**, según lo que necesites y cuántas sucursales tengas. Si alguna te interesa, no esperes al último."},{"id":"s1","tipo":"separador"},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20quiero%20ver%20que%20mas%20puede%20hacer%20Sacs%20por%20mi%20operacion","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Si ninguno te mueve, también está bien. Contéstame «ya estoy bien así» y dejo de mandarlos."}]'::jsonb where id='12e33a8c-ff8a-4f83-8941-ea13eafe511b';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/axo-asistente.jpg","alt":"","etiqueta":"Axo · 2 de 10","titulo":"Axo hace el trabajo, no te lo explica"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, empecemos por el que más sorprende. 🤖"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Axo no es un chat de ayuda"},{"id":"t2","tipo":"texto","texto":"La diferencia es toda. Un asistente normal te dice: *«ve a Inventarios, luego a Nivelación, luego a Configuración…»*. Axo **te lleva a la pantalla** — y si se lo pides, lo hace él."},{"id":"l1","tipo":"lista","items":["⚙️ **Configura la nivelación por chat**: días de cobertura, ventana de análisis, tiempo de traslado.","🚀 **Lanza una corrida** y regenera el cubo de demanda.","🚫 **Excluye un producto de una tienda** sin que abras nada.","🧭 Y al terminar **te lleva a ver el resultado**, no te deja adivinando."]},{"id":"a1","tipo":"aviso","texto":"Con los **mismos permisos** que exige la pantalla: quien no puede correr una nivelación tampoco puede pedírsela al asistente. Y siempre con el botón de confirmar antes de tocar nada."},{"id":"s1","tipo":"separador"},{"id":"t3","tipo":"texto","texto":"Lo que se ahorra no es tiempo de clics. Es el tiempo de acordarse de dónde estaba cada cosa."},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20quiero%20ver%20Axo%20funcionando%20en%20mi%20cuenta","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Sirve para quien no es el dueño. Una encargada puede pedirle cosas que no sabría configurar sola."}]'::jsonb where id='556af0a6-ce58-4214-b1cb-80c11bf41a8c';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/equipo-rh.jpg","alt":"","etiqueta":"Colaboradores · 3 de 10","titulo":"Tus colaboradores, en un lugar"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, hoy el que casi nadie pide y todos necesitan. 👥"},{"id":"t2","tipo":"texto","texto":"La operación de una tienda se lleva en el sistema. **La de su gente, casi siempre en un cuaderno** — o en la cabeza de quien administra."},{"id":"s0","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Lo que entra al módulo"},{"id":"l1","tipo":"lista","items":["🕘 **Asistencias**: entradas, salidas, retardos y faltas, con su reporte.","📄 **Contratos** y sus vencimientos, sin buscar en una carpeta.","⚠️ **Actas administrativas**, escritas y firmadas donde quedan guardadas.","🌡️ **Clima laboral**, para saber cómo está tu equipo antes de que renuncie.","📁 **El expediente completo** de cada quien, en una sola pantalla."]},{"id":"a1","tipo":"aviso","texto":"La diferencia se nota el día que la necesitas: cuando hay que sostener una decisión con alguien, tener el acta y las asistencias a la mano **cambia por completo esa conversación**."},{"id":"s1","tipo":"separador"},{"id":"t2b","tipo":"texto","texto":"Y para el dueño hay algo más: dejar de ser el único que sabe quién llegó tarde el mes pasado."},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20quiero%20ver%20el%20modulo%20de%20Empleados","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"}]'::jsonb where id='fedd6187-e719-4e5d-8b2e-0a604ea85315';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/finanzas.jpg","alt":"","etiqueta":"Finanzas · 4 de 10","titulo":"A dónde se fue el dinero"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, este es de los que más rápido se pagan solos. 🏦"},{"id":"t2","tipo":"texto","texto":"Sacs ya te dice **cuánto vendiste**. Lo que casi siempre vive aparte —en Excel, en el banco, en la cabeza del contador— es la otra mitad: a dónde se fue."},{"id":"s0","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Administración"},{"id":"l1","tipo":"lista","items":["💸 **Gastos** por categoría y por sucursal, con sus comprobantes.","📥 **Cuentas por cobrar**: quién te debe, desde cuándo y cuánto.","📤 **Cuentas por pagar**: a quién le debes y qué vence esta semana.","🏛️ **Cuentas de efectivo y bancos**, con la conciliación contra tus movimientos reales."]},{"id":"a1","tipo":"aviso","texto":"Cuando venta y gasto viven en el mismo lugar, la pregunta «¿este mes ganamos?» deja de contestarse con una corazonada a fin de mes."},{"id":"s1","tipo":"separador"},{"id":"t3","tipo":"texto","texto":"Y si ya usas una parte —muchos llevan gastos y nada más— vale la pena ver lo demás: casi siempre es lo que le falta al reporte que ya revisas."},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20quiero%20ver%20el%20modulo%20de%20Administracion","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"}]'::jsonb where id='287abaa2-6c59-44d1-bf2f-920f3a3692b2';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/cedis.jpg","alt":"","etiqueta":"Nivelación · 5 de 10","titulo":"Que el sistema te diga qué mover"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, este es el que cambia cómo se compra. 📦"},{"id":"t2","tipo":"texto","texto":"Hoy alguien decide qué mandar a cada sucursal y qué pedirle al proveedor. Lo decide bien —lleva años haciéndolo— pero lo decide **a ojo, y una cabeza a la vez**."},{"id":"s0","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Nivelación"},{"id":"t3","tipo":"texto","texto":"El sistema mira lo que tienes, lo que se está vendiendo en cada punto y las reglas que tú definas. Y te dice, producto por producto:"},{"id":"l1","tipo":"lista","items":["🔁 **Qué transferir entre sucursales** — la talla que sobra allá y falta acá.","🏭 **Qué mandar desde el CEDIS** y en qué orden de prioridad.","🛒 **Qué comprar de verdad**, después de haber movido lo que ya pagaste."]},{"id":"a1","tipo":"aviso","texto":"Ese último punto es el que más dinero libera: **antes de comprar, acomodar**. Casi siempre una parte de lo que ibas a pedir ya está en tu propia bodega, en la tienda equivocada."},{"id":"i1","alt":"Pantalla de nivelación de Sacs con el análisis por sucursal","pie":"Pantalla real. Las reglas las pones tú.","src":"https://www.sacscloud.com/email/trial/trial-nivelacion.jpg","tipo":"imagen"},{"id":"s1","tipo":"separador"},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20quiero%20ver%20el%20dashboard%20de%20nivelacion","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Funciona con las reglas de tu negocio, no con un promedio de la industria. Si tu tienda del centro vende distinto, la nivelación lo respeta."}]'::jsonb where id='bb62585c-55df-4159-9bec-799a950b1896';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/automatizacion.jpg","alt":"","etiqueta":"Automatización · 6 de 10","titulo":"Si tu proceso es distinto, se programa"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, el último de la lista, y el menos conocido. 🧩"},{"id":"t2","tipo":"texto","texto":"Todo sistema obliga a acomodarse un poco. Pero hay cosas que **no deberían acomodarse**: la forma particular en que tu negocio hace algo, y que es justo lo que te distingue."},{"id":"s0","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Qué se puede personalizar"},{"id":"t3","tipo":"texto","texto":"Prácticamente cualquier flujo. Algunos que ya corren en cuentas reales:"},{"id":"l1","tipo":"lista","items":["🔗 **Un paso de autorización** antes de que algo avance.","📨 **Un aviso automático** a quien tiene que enterarse, por correo o WhatsApp.","📑 **Un documento propio** que hoy se llena a mano cada vez.","🔄 **Una conexión** con un sistema que ya usas y no quieres dejar."]},{"id":"a1","tipo":"aviso","texto":"La pregunta útil no es «¿Sacs lo hace?» sino **«¿esto que hago cada semana a mano, se puede automatizar?»**. Casi siempre sí — y lo que implica se ve contigo, sobre tu proceso."},{"id":"s1","tipo":"separador"},{"id":"t4","tipo":"texto","texto":"Si hay algo así en tu operación, cuéntamelo. Aunque sea para decirte que no vale la pena."},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20tengo%20un%20proceso%20que%20hago%20a%20mano%20y%20quiero%20saber%20si%20se%20puede%20automatizar","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"}]'::jsonb where id='1c188573-17f7-492d-9937-2eddf8fb41c8';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wow-vitrina.jpg","alt":"","etiqueta":"Tu plan · 7 de 10","titulo":"Lo que trae el plan que sigue"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, hasta ahora te he mostrado extensiones sueltas. Hoy va lo otro: **el escalón completo**."},{"id":"t2","tipo":"texto","texto":"Estás en **{{plan_actual}}**. El que sigue es **{{plan_siguiente}}**, y no te voy a mandar la tabla comparativa — te digo las tres cosas que de verdad cambian en tu semana:"},{"id":"s0","tipo":"separador"},{"id":"l1","tipo":"lista","items":["✅ **{{punto_1}}**","✅ **{{punto_2}}**","✅ **{{punto_3}}**"]},{"id":"s1","tipo":"separador"},{"id":"a1","tipo":"aviso","texto":"Subir de plan no es empezar de nuevo: **conservas todo** —tu catálogo, tus clientes, tu histórico— y lo que cambia es qué puedes hacer con ello. Lo que implica en tu caso lo vemos contigo, según tus sucursales."},{"id":"t3","tipo":"texto","texto":"Y si con {{plan_actual}} vas bien, dímelo sin pena. No todo el mundo necesita subir, y prefiero decírtelo yo a que lo descubras pagando de más."},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20quiero%20saber%20que%20trae%20el%20plan%20que%20sigue%20en%20mi%20caso","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Si lo que te interesa es una sola cosa del que sigue, a veces se resuelve con una extensión y sale más barato. También te lo digo."}]'::jsonb where id='3fe0eaf3-dbe9-4ac4-a5e7-60a8bab86bdd';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wow-espejo.jpg","alt":"","etiqueta":"Catálogo con IA · 8 de 10","titulo":"Tu catálogo, con inteligencia artificial"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, este es el que más cara pone la gente cuando lo ve. 📸"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Dos cosas, y las dos salen de tu catálogo"},{"id":"t2","tipo":"texto","texto":"**Modelos con IA.** Subes la foto de la prenda —la de siempre, sobre el maniquí o colgada— y sale puesta en una persona. Distintos cuerpos, distintos tonos de piel, el fondo que quieras. Sin sesión, sin estudio y sin agendar a nadie."},{"id":"i1","alt":"Clienta frente a un espejo de probador con una prenda","pie":"La prenda es la tuya. El modelo, no.","src":"https://www.sacscloud.com/email/moda/moda-probador.jpg","tipo":"imagen"},{"id":"t3","tipo":"texto","texto":"**Probador virtual.** Tu clienta ve cómo se le vería a ella, no a una modelo. Y como sale de tu catálogo, lo que se prueba es lo que **sí tienes** en su talla — no una foto bonita de algo agotado."},{"id":"a1","tipo":"aviso","texto":"Lo que resuelve no es el diseño: es el cuello de botella. Publicar deja de depender de que alguien tenga la tarde libre para fotografiar cincuenta prendas nuevas."},{"id":"s1","tipo":"separador"},{"id":"t4","tipo":"texto","texto":"Si quieres, mándame una foto de un producto tuyo por WhatsApp y te la regreso hecha. Es la forma más rápida de que veas si te sirve."},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20quiero%20probar%20las%20fotos%20con%20IA%20con%20un%20producto%20mio","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"}]'::jsonb where id='48cd3e60-099c-40e2-a8db-670ae708953b';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/renta-gala.jpg","alt":"","etiqueta":"Renta · 9 de 10","titulo":"Rentar en vez de vender"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, el último, y es un cambio de modelo más que un módulo. 👗"},{"id":"t2","tipo":"texto","texto":"Una prenda cara se vende una vez. **Rentada deja dinero seis, ocho, doce veces** — y el problema nunca fue la idea, fue llevar la cuenta."},{"id":"s0","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Renta, dentro del mismo sistema"},{"id":"l1","tipo":"lista","items":["📅 **Calendario por prenda**: quién la tiene, qué días está apartada y cuándo regresa.","💵 **Depósito en garantía**, con su movimiento en caja al salir y al volver.","🧵 **Estado a la devolución**: si vuelve dañada, se cobra el ajuste y queda en su ficha.","🔁 **Cuánto lleva generado cada pieza** contra lo que costó."]},{"id":"a1","tipo":"aviso","texto":"Ese último número es el que nadie tiene: **cuánto ha pagado esa prenda de sí misma**. Con eso se decide qué comprar la próxima temporada y qué mandar a liquidación cuando ya se pagó sola."},{"id":"s1","tipo":"separador"},{"id":"t3","tipo":"texto","texto":"Y si vendes y rentas a la vez, es el mismo inventario: una prenda apartada para renta no aparece disponible para venta ese fin de semana."},{"id":"t4","tipo":"texto","texto":"Funciona igual para vestidos de gala, trajes, XV años y disfraces de temporada. Todo lo que sale y vuelve."},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20quiero%20ver%20como%20funciona%20la%20renta%20de%20productos","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"}]'::jsonb where id='ddab1967-27bd-46c3-813e-94763f32061b';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/mostrador.jpg","alt":"","etiqueta":"Lo que sigue · 10 de 10","titulo":"¿Alguno te movió?"},{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, te mandé ocho cosas en estos meses:"},{"id":"l1","tipo":"lista","items":["🤖 **Axo** — el asistente que ejecuta.","👥 **Empleados** — asistencias, contratos, actas, clima.","🏦 **Administración** — gastos, cobrar y pagar, bancos.","📦 **Nivelación** — qué mover y qué comprar.","🧩 **Personalizaciones** — automatizar un proceso tuyo.","⬆️ **El plan que sigue** — {{plan_siguiente|el siguiente escalón}}.","📸 **Catálogo con IA** — modelos y probador virtual.","👗 **Renta de productos** — la misma prenda, muchas veces."]},{"id":"t2","tipo":"texto","texto":"No espero que te interesen todas. Con que **una** te haya hecho pensar «esto sí me serviría», este correo valió la pena."},{"id":"s0","tipo":"separador"},{"id":"t3","tipo":"texto","texto":"Y si es así, la sesión es de 45 minutos: te enseño esa —solo esa— con tu propia cuenta abierta, y te digo con franqueza si te conviene o no. **Todas son extensiones de tu plan**, así que lo que implica cada una lo vemos ahí mismo, sobre tu caso."},{"id":"a1","tipo":"aviso","texto":"**Si ninguna te movió, contéstame «ya estoy bien así»** y dejo de mandarte esta serie. Prefiero eso a seguir ocupándote la bandeja."},{"id":"s1","tipo":"separador"},{"id":"b1a","sub":"45 minutos · sin costo · con alguien que conoce tu cuenta","href":"https://www.sacscloud.com/agendar/crecimiento","tipo":"boton","align":"center","texto":"📅 Agendar 45 minutos"},{"id":"b1b","sub":"Si prefieres preguntar sin agendar nada","href":"https://wa.me/525593027234?text=Hola,%20me%20intereso%20una%20de%20las%20cosas%20que%20me%20mandaste","tipo":"boton","align":"center","color":"#2AB5A0","texto":"💬 O escríbenos por WhatsApp"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Y si algo de lo que ya tienes no te está funcionando como esperabas, también quiero saberlo. Eso pesa más que cualquier módulo nuevo."}]'::jsonb where id='4b6dec14-a39e-4764-ba88-254e2f1f8b71';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/sesion-video.jpg","alt":"","etiqueta":"Tu sesión · 1 de 5","titulo":"Tu sesión quedó agendada"},{"id":"t1","tipo":"texto","texto":"¡Quedó! Tu sesión consultiva está agendada{{fecha_sesion|}} — y va a ser con TU negocio, no con demos de relleno."},{"id":"b1","sub":"un clic y queda en tu agenda","href":"{{link_gcal|https://www.sacscloud.com/agendar}}","tipo":"boton","align":"center","texto":"Agregar a mi Google Calendar"},{"id":"t2","tipo":"texto","texto":"Soy Andrea y yo la llevo. Lo único que te pido tener a la mano:"},{"id":"l1","tipo":"lista","items":["2-3 productos tuyos con sus variantes (los cargamos en vivo)","Cómo llevas hoy tus apartados y tu inventario","Si vendes en línea o por WhatsApp, el link de tu tienda o catálogo"]},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Y lo más valioso: tus preguntas"},{"id":"t3","tipo":"texto","texto":"Responde este correo con las dudas que traigas — las que sean. Cada pregunta que me mandes antes me deja llegar con TU respuesta preparada, no con un guion."},{"id":"rg","tipo":"aviso","texto":"¿Se te complicó el horario? Reagenda en 1 minuto aquí: {{link_reagendar|https://www.sacscloud.com/agendar}} — tu lugar no se pierde."},{"id":"f1","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. ¿No sabes qué preguntar? Empieza por lo que más tiempo te roba hoy: por ahí abrimos."}]'::jsonb where id='22222222-3333-4444-8555-666666666601';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/consultora-prepara.jpg","alt":"","etiqueta":"Tu sesión · 2 de 5","titulo":"Ya estoy preparando tu sesión"},{"id":"t1","tipo":"texto","texto":"Mientras llega tu sesión, yo ya estoy armando tu caso."},{"id":"t2","tipo":"texto","texto":"Llevo años implementando Sacs con negocios de retail de todos los tamaños: desde la primera tienda que deja la libreta, hasta operaciones que venden en tienda, en línea y en eventos al mismo tiempo. Mi trabajo no es enseñarte pantallas: es dejar TU operación andando, de inicio a fin."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Este es el momento de las preguntas específicas"},{"id":"t3","tipo":"texto","texto":"¿Tallas que se agotan en una sucursal y sobran en otra? ¿Apartados en libreta? ¿Tu tienda en línea que no cuadra con el mostrador? Respóndeme este correo con tu caso y llego a la sesión con la solución montada."},{"id":"b1","sub":"por WhatsApp o respondiendo este correo","href":"https://wa.me/525593027234","tipo":"boton","align":"center","texto":"Mandar mis preguntas"},{"id":"rg","tipo":"aviso","texto":"¿Se te complicó el horario? Reagenda en 1 minuto aquí: {{link_reagendar|https://www.sacscloud.com/agendar}} — tu lugar no se pierde."},{"id":"f1","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Ninguna pregunta es demasiado básica ni demasiado rara — las raras son mis favoritas."}]'::jsonb where id='22222222-3333-4444-8555-666666666602';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/pos.jpg","alt":"","etiqueta":"Tu sesión · 3 de 5","titulo":"Así serán tus 20 minutos"},{"id":"t1","tipo":"texto","texto":"Mucha gente llega a su sesión esperando un tour de pantallas. La tuya no va a ser así."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Esto es lo que vamos a hacer, en vivo"},{"id":"l1","tipo":"lista","items":["Cargamos 2-3 productos tuyos con sus variantes","Hacemos una venta completa: cobro, ticket, y el inventario se descuenta solo","Vemos tus existencias como se verían con más de un punto de venta","Respondemos TUS preguntas — las que me hayas mandado y las que salgan ahí","Sales con un plan de implementación de inicio a fin, por escrito"]},{"id":"i1","alt":"El punto de venta Sacs en una tienda","pie":"Tu punto de venta — con tus productos, no con datos de mentira.","src":"https://www.sacscloud.com/images/plan-vende.jpg","tipo":"imagen"},{"id":"t2","tipo":"texto","texto":"¿Ya me mandaste tus preguntas? Todavía estás a tiempo: responde este correo y las metemos a la agenda."},{"id":"rg","tipo":"aviso","texto":"¿Se te complicó el horario? Reagenda en 1 minuto aquí: {{link_reagendar|https://www.sacscloud.com/agendar}} — tu lugar no se pierde."},{"id":"pd","tipo":"texto","texto":"P.D. La sesión es tuya: si algo de tu operación te quita el sueño, ese es exactamente el tema."}]'::jsonb where id='22222222-3333-4444-8555-666666666603';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/feria.jpg","alt":"","etiqueta":"Un caso real · 4 de 5","titulo":"De un pop-up a cientos de tiendas a la vez"},{"id":"t1","tipo":"texto","texto":"Antes de tu sesión, un caso que vale la pena conocer."},{"id":"t2","tipo":"texto","texto":"LiveShow es una empresa transnacional de merchandising de eventos: opera desde una tienda pop-up de un artista hasta CIENTOS de puntos de venta al mismo tiempo en eventos masivos. Toda esa operación —inventario, traspasos, cortes, venta en vivo— corre sobre Sacs."},{"id":"i1","alt":"Torre de control de una operación multi-tienda","pie":"La misma plataforma: de 1 tienda a cientos operando a la vez.","src":"https://www.sacscloud.com/images/plan-automatiza.jpg","tipo":"imagen"},{"id":"t3","tipo":"texto","texto":"¿Y los negocios de a pie? En Google tenemos más de 100 reseñas con 4.8 de calificación — dueños de tiendas contando su propia experiencia, con su nombre."},{"id":"m1","tipo":"metricas","items":[{"cifra":"★ 4.8/5","texto":"en Google Reviews"},{"cifra":"100+","texto":"reseñas de dueños reales"},{"cifra":"+14 años","texto":"acompañando al retail"}]},{"id":"t4","tipo":"texto","texto":"Tu sesión usa la misma plataforma y el mismo método: tu operación, en vivo, y un plan claro al salir. Si quieres que veamos algo de este caso aplicado a tu negocio, respóndeme y lo preparo."},{"id":"rg","tipo":"aviso","texto":"¿Se te complicó el horario? Reagenda en 1 minuto aquí: {{link_reagendar|https://www.sacscloud.com/agendar}} — tu lugar no se pierde."},{"id":"pd","tipo":"texto","texto":"P.D. El sistema que aguanta cientos de tiendas en un estadio es el mismo que arranca contigo en una sola — nada más que a ti te toca sin filas."}]'::jsonb where id='22222222-3333-4444-8555-666666666604';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/miercoles.jpg","alt":"","etiqueta":"Tu sesión · 5 de 5","titulo":"¿Se te movió la agenda?"},{"id":"t1","tipo":"texto","texto":"La semana de un negocio cambia en un día — nos pasa a todos."},{"id":"t2","tipo":"texto","texto":"Si tu sesión ya no te acomoda, muévela: reagendar toma 1 minuto, tu lugar no se pierde y tus preguntas siguen en mi lista."},{"id":"b1","sub":"eliges día y hora en un minuto","href":"{{link_reagendar|https://www.sacscloud.com/agendar}}","tipo":"boton","align":"center","texto":"Reagendar mi sesión"},{"id":"a1","tipo":"aviso","texto":"Si prefieres, respóndeme por aquí o por WhatsApp y yo la muevo por ti."},{"id":"f1","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Y si ya no es el momento, dímelo sin pena: mejor un «ahora no» claro que dejarte en visto."}]'::jsonb where id='22222222-3333-4444-8555-666666666605';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/consultora.jpg","alt":"","etiqueta":"Para empezar","titulo":"Soy Andrea, tu consultora en Sacs"},{"id":"t1","tipo":"texto","texto":"¿Cuántas horas se te fueron esta semana en averiguar qué tallas quedan en cada tienda?\n\nSoy Andrea, tu consultora asignada en Sacs — el sistema especializado en retail de moda: boutiques, ropa, calzado y accesorios."},{"id":"t2","tipo":"texto","texto":"Mi trabajo no es darte un tour por un sistema. Es implementar TU operación contigo, de inicio a fin: catálogo con tallas y colores, apartados, sucursales y venta en línea."},{"id":"f1","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"a1","tipo":"aviso","texto":"📲 También te escribo por WhatsApp desde nuestro número oficial. Puedes responderme por aquí o por allá — como te acomode."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"El mejor primer paso"},{"id":"t3","tipo":"texto","texto":"Una sesión consultiva sin costo. Vemos tu boutique, cargamos algunas de tus prendas con sus tallas y colores, y sales viendo tu operación funcionando en tiempo real. No es un tour: es tu negocio, en vivo."},{"id":"bt","sub":"20 minutos · sin costo · con tu boutique","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia1","tipo":"boton","align":"center","texto":"Agendar mi sesión consultiva →"},{"id":"pd","tipo":"texto","texto":"P.D. Si hoy vendes por WhatsApp o Instagram y el inventario vive en una libreta, no llegas tarde: justo ahí es donde más rápido se nota el cambio."},{"id":"m1","tipo":"metricas","items":[{"cifra":"+14 años","texto":"acompañando al retail"},{"cifra":"★ 4.8/5","texto":"en Google Reviews"},{"cifra":"3,000+ marcas","texto":"han operado con nosotros"}]}]'::jsonb where id='085c5aee-cdf8-44b3-adff-610b246d5077';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wow-planta.jpg","alt":"","etiqueta":"Multisucursal · 2 de 8","titulo":"La talla M que se agotó en Centro"},{"id":"t1","tipo":"texto","texto":"La blusa talla M se agotó en tu tienda del Centro. En Norte hay cuatro… juntando polvo.\n\nNo es mala suerte: es lo que pasa cuando cada sucursal solo ve su propio inventario."},{"id":"t2","tipo":"texto","texto":"De un lado pierdes ventas de la prenda que SÍ rota; del otro, esa mercancía va directo a la rebaja de fin de temporada. Y en moda, la temporada no espera."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Lo que ve una marca de moda con Sacs"},{"id":"l1","tipo":"lista","items":["Existencias vivas por talla y color en TODAS tus tiendas — al segundo, no al corte del mes","Traspasos con tránsito controlado: la prenda que salió de Centro llega a Norte, sin hoyos en el camino","Precios y promociones por plaza — cada mercado con su estrategia","Tu tienda en línea y TikTok Shop venden del MISMO inventario que el piso de venta"]},{"id":"i1","alt":"Gerente de una marca de moda revisando existencias por sucursal en Sacs","pie":"Todas tus tiendas, un solo inventario — así se ve antes de abrir la caja.","src":"https://www.sacscloud.com/images/cadencia-1.jpg","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia2","tipo":"imagen"},{"id":"t3","tipo":"texto","texto":"El flujo se cierra completo: detectar el desbalance, mover la prenda y venderla donde sí rota. En la sesión consultiva lo vemos con tus propias tiendas."},{"id":"bt","sub":"20 minutos · sin costo · con tu boutique","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia2","tipo":"boton","align":"center","texto":"Agendar mi sesión consultiva →"},{"id":"pd","tipo":"texto","texto":"P.D. ¿Solo tienes una tienda por ahora? Mejor: dejar el inventario listo ANTES de abrir la segunda es lo que hace que la segunda sí sea negocio."}]'::jsonb where id='96c99772-d718-4623-8ed9-2bb10e792f55';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/ia-inventario.jpg","alt":"","etiqueta":"Inventario con IA · 3 de 8","titulo":"¿Y si tu inventario te avisara antes?"},{"id":"t1","tipo":"texto","texto":"¿Te ha pasado? Se agota la talla que más vendes y te quedas con una pila de la que nadie pide.\n\nEn moda el inventario no es un número: son tallas, colores y temporadas. Y cuidarlo a mano deja de alcanzar cuando creces."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Un inventario que se cuida solo"},{"id":"l1","tipo":"lista","items":["La IA calcula mínimos y máximos por prenda, talla y sucursal — y te avisa ANTES de que la curva de tallas se rompa","La orden de compra sugerida te llega al teléfono: la revisas y la apruebas desde donde estés","¿No sabes qué resurtir para la temporada? Pregúntale a la IA dentro del sistema — te contesta con TUS números","La nivelación mueve las prendas a la sucursal donde sí rotan, antes de que terminen en rebaja"]},{"id":"i1","alt":"Aprobando una orden de compra desde el teléfono con Sacs","pie":"De la alerta a la orden de compra aprobada — sin abrir la laptop.","src":"https://www.sacscloud.com/images/cadencia-2.jpg","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia3","tipo":"imagen"},{"id":"a1","tipo":"aviso","texto":"En tu sesión consultiva mapeamos TU catálogo: sales viendo el flujo completo — de la alerta de la IA a la orden de compra — con tus propias prendas."},{"id":"bt","sub":"20 minutos · sin costo · con tu boutique","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia3","tipo":"boton","align":"center","texto":"Agendar mi sesión consultiva →"},{"id":"pd","tipo":"texto","texto":"P.D. La rebaja de fin de temporada no es un destino: casi siempre es una prenda que pasó demasiado tiempo en la tienda equivocada."}]'::jsonb where id='81a3ea9d-b642-446c-b12e-44965e23cd97';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/clienta-regresa.jpg","alt":"","etiqueta":"Fidelización · 4 de 8","titulo":"Que tu clienta vuelva, no que compre una vez"},{"id":"t1","tipo":"texto","texto":"¿Tu clienta de la temporada pasada ya vio la colección nueva?\n\nEn moda, la clienta que regresa cada temporada vale más que diez compras de paso — y hacerla volver no debería depender de tu memoria."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Lealtad que vive en tu caja"},{"id":"l1","tipo":"lista","items":["Puntos y cashback que se acumulan y canjean EN CAJA — sin apps externas ni tarjetitas","Apartados sin libreta: la prenda se separa, cada abono queda registrado y nada se pierde","El ticket viaja por WhatsApp — y con él, las razones para volver","Campañas automáticas: aviso de colección nueva a quien ya te compró, y un empujón a la clienta que dejó de venir"]},{"id":"i1","alt":"Una clienta acumulando puntos de lealtad en caja con Sacs","pie":"La lealtad se siente en cada compra — y la clienta lo nota.","src":"https://www.sacscloud.com/images/cadencia-3.jpg","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia4","tipo":"imagen"},{"id":"t2","tipo":"texto","texto":"Nada de esto es una app aparte: vive dentro del punto de venta, así tu equipo lo usa sin pensarlo."},{"id":"bt","sub":"20 minutos · sin costo · con tu boutique","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia4","tipo":"boton","align":"center","texto":"Agendar mi sesión consultiva →"},{"id":"pd","tipo":"texto","texto":"P.D. Conseguir una clienta nueva cuesta entre 5 y 7 veces más que hacer volver a una que ya te compró. La colección nueva es la excusa perfecta para empezar."}]'::jsonb where id='041f45ee-fb54-43d1-8177-6583bb148a50';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/liveshow.jpg","alt":"","etiqueta":"Un caso real · 5 de 8","titulo":"Cien cajas vendiendo a la vez, sin internet"},{"id":"t1","tipo":"texto","texto":"Déjame contarte de un caso que no es de moda — y por qué es justo el que más te conviene conocer.\n\nLiveshow Merchandising vende la mercancía oficial de conciertos y festivales: playeras, sudaderas, gorras. Todo su año se juega en unas cuantas noches, cuando setenta y cinco mil personas quieren comprar al mismo tiempo y la fila no puede parar."},{"id":"t2","tipo":"texto","texto":"Antes, una caída del sistema les costó el veinte por ciento de las ventas en dos horas. Hoy operan más de cien puntos de venta simultáneos y procesaron ciento cincuenta mil transacciones en una temporada, sin un solo error."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Lo que hoy opera con Sacs"},{"id":"l1","tipo":"lista","items":["Cobro sin internet — cuando la señal se cae, la caja sigue vendiendo y todo se sincroniza después","Más de cien puntos de venta a la vez, con el inventario de todos a la vista en el mismo tablero","Las auditorías manuales de doce horas desaparecieron: el corte sale solo al cerrar"]},{"id":"i1","alt":"Punto de venta operando en un festival con Sacs","pie":"Cien cajas vendiendo a la vez, sin internet y sin perder un ticket.","src":"https://www.sacscloud.com/images/case-liveshow.webp","tipo":"imagen"},{"id":"h2","tipo":"encabezado","nivel":2,"texto":"¿Y tu boutique qué?"},{"id":"t3","tipo":"texto","texto":"Tu negocio también tiene sus noches de festival: el Buen Fin, una venta nocturna, el arranque de temporada, un liveshow. Son los días en que entra la mayor parte del dinero del mes… y justo cuando el control se rompe.\n\nSi el sistema aguanta cien cajas en un festival, aguanta tu mejor sábado — con tallas, colores y apartados encima."},{"id":"a1","tipo":"aviso","texto":"Andrea, tu consultora, acompañó estos procesos de inicio a fin — es la misma que te va a acompañar a ti."},{"id":"bt","sub":"20 minutos · sin costo · con tu boutique","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia5","tipo":"boton","align":"center","texto":"Agendar mi sesión consultiva →"},{"id":"pd","tipo":"texto","texto":"P.D. Lo que se rompe en un pico de venta no es el cobro: es saber qué te queda. Eso se ve en veinte minutos con tus propias prendas."}]'::jsonb where id='0a5e5a09-1122-447e-acc7-750eca29d769';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/live-selling.jpg","alt":"","etiqueta":"Innovación · 6 de 8","titulo":"Vender en vivo, en línea y en tienda"},{"id":"t1","tipo":"texto","texto":"Las marcas de ropa que más crecen ya no venden solo detrás del mostrador: venden en vivo, en línea y en tienda — con un solo inventario."},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Lo que ya puedes operar hoy"},{"id":"l1","tipo":"lista","items":["Liveshows: vende ropa en vivo con fila ordenada y escáner desde el teléfono — sin caos al entregar","Tienda en línea y TikTok Shop conectados a tu inventario real: se vende la última talla M y se baja sola de la página","Tu teléfono como centro de mando: ventas, alertas y órdenes de compra desde donde estés","Pídele a la IA que te avise cuando la prenda estrella esté por agotarse — y te escribe ella"]},{"id":"t2","tipo":"texto","texto":"No son funciones sueltas: cada pieza cierra un flujo completo de tu operación de moda, de la percha al envío."},{"id":"i0","alt":"Una venta completa en el punto de venta de Sacs","pie":"Una venta completa en el punto de venta de Sacs — 11 segundos.","src":"https://www.sacscloud.com/images/posdemo-email.gif","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia6","tipo":"imagen"},{"id":"bt","sub":"20 minutos · sin costo · con tu boutique","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia6","tipo":"boton","align":"center","texto":"Agendar mi sesión consultiva →"},{"id":"pd","tipo":"texto","texto":"P.D. ¿Nunca has hecho un liveshow? No importa: en la sesión te cuento cómo arrancan las marcas que venden ropa en vivo con Sacs."}]'::jsonb where id='f32679f2-a98a-4c49-a004-bd7f25dbe5ce';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/mostrador.jpg","alt":"","etiqueta":"Planes · 7 de 8","titulo":"¿En qué etapa está tu boutique?"},{"id":"t1","tipo":"texto","texto":"¿Tu marca está arrancando, abriendo sucursales o ya vive de su clientela?\n\nEn Sacs no pagas por lo que no usas: hay un plan para cada etapa de una marca de moda. Ubica el tuyo:"},{"id":"h1","tipo":"encabezado","texto":"VENDE · Tu primera tienda"},{"id":"i1","alt":"Primera boutique arrancando con el punto de venta de Sacs","pie":"Para tu primera boutique o tu primer punto de venta","src":"https://www.sacscloud.com/images/plan-vende.jpg","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia7","tipo":"imagen"},{"id":"t2","tipo":"texto","texto":"Para la marca que empieza a vender: tu primer punto de venta, catálogo con tallas y colores desde el día uno y ticket digital. Si hoy cobras con libreta y vendes por WhatsApp o Instagram sin control de inventario, te toca VENDE."},{"id":"h2","tipo":"encabezado","texto":"CONTROLA · Abriste la segunda sucursal"},{"id":"i2","alt":"Existencias por sucursal de una marca de moda","pie":"Para marcas de 2 a 5 tiendas que ya mueven prendas entre sucursales","src":"https://www.sacscloud.com/images/plan-controla.jpg","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia7","tipo":"imagen"},{"id":"t3","tipo":"texto","texto":"Para la boutique que ya abrió su segunda (o quinta) tienda y las tallas se agotan en una mientras sobran en otra: existencias por sucursal, traspasos y mínimos por talla. Si ya no sabes qué hay en cada tienda sin hablarle a alguien, te toca CONTROLA."},{"id":"h3","tipo":"encabezado","texto":"FIDELIZA · Ya tienes clientela propia"},{"id":"i3","alt":"Clienta fiel con sus puntos de lealtad","pie":"Para boutiques que viven de que sus clientas regresen cada temporada","src":"https://www.sacscloud.com/images/plan-fideliza.jpg","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia7","tipo":"imagen"},{"id":"t4","tipo":"texto","texto":"Para el negocio establecido: puntos, cashback, apartados y campañas para que quien te compró la temporada pasada vuelva por la colección nueva. Si tus ventas dependen de clientas que regresan — o quieres que dependan de eso — te toca FIDELIZA."},{"id":"h4","tipo":"encabezado","texto":"AUTOMATIZA · Tu operación ya es grande"},{"id":"i4","alt":"Tablero multi-sucursal de una marca de moda","pie":"Para marcas multi-sucursal que necesitan que el sistema trabaje solo","src":"https://www.sacscloud.com/images/plan-automatiza.jpg","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia7","tipo":"imagen"},{"id":"t5","tipo":"texto","texto":"Para la marca grande o multi-región: IA que vigila tu inventario por talla y sucursal, liveshows, tienda en línea y TikTok Shop del mismo inventario. Si tu equipo pasa el día armando reportes a mano, te toca AUTOMATIZA."},{"id":"t6","tipo":"texto","texto":"En los 4, el acompañamiento es el mismo: implementamos contigo proceso por proceso hasta que tu operación corre sola. Y en la sesión consultiva te digo con honestidad cuál te toca — a veces es el más chico, y está perfecto."},{"id":"bt","sub":"20 minutos · sin costo · con tu boutique","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia7","tipo":"boton","align":"center","texto":"Agendar mi sesión consultiva →"},{"id":"pd","tipo":"texto","texto":"P.D. Creces de plan cuando tu marca crece — no antes. Nadie te va a empujar al plan grande."}]'::jsonb where id='55d84858-2358-4d66-b40f-4e95523d3e4d';
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id":"portada","tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/vitrina-noche.jpg","alt":"","etiqueta":"Último correo · 8 de 8","titulo":"Mi último correo"},{"id":"t1","tipo":"texto","texto":"Este es mi último correo — no te voy a llenar la bandeja.\n\nSolo quiero dejarte claro qué queda abierto para ti, porque no es una demo de pantallas."},{"id":"t2","tipo":"texto","texto":"Es una sesión consultiva sin costo donde vemos TU boutique: tu catálogo con tallas y colores, tus apartados, tus sucursales, tu venta en línea. Lo ejecutamos en el sistema en tiempo real y te llevas un plan de implementación de inicio a fin."},{"id":"f1","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"t3","tipo":"texto","texto":"Quedo a un WhatsApp de distancia. Cuando sea tu momento — la colección nueva, la segunda sucursal, el cierre de temporada — retomamos en 5 minutos justo donde quedamos."},{"id":"bt","sub":"Y si hoy no es el momento, no pasa nada — aquí seguimos.","href":"https://www.sacscloud.com/agendar/demo?utm_source=cadencia_leads&utm_medium=email&utm_campaign=seguimiento&utm_content=dia8","tipo":"boton","align":"center","texto":"Agendar mi sesión consultiva →"},{"id":"pd","tipo":"texto","texto":"P.D. Si te llevas una sola idea de estos correos, que sea esta: la prenda que se agota en una tienda y sobra en otra sí tiene solución — y verla con tus números toma 20 minutos."},{"id":"m1","tipo":"metricas","items":[{"cifra":"+14 años","texto":"acompañando al retail"},{"cifra":"★ 4.8/5","texto":"en Google Reviews"},{"cifra":"3,000+ marcas","texto":"han operado con nosotros"}]}]'::jsonb where id='8bfeaaa3-a21c-4f92-8561-c437ec98d314';
commit;
